/// Test that std.fermi::fermi_eq boundary can be mocked.
#[test]
fn test_boundary_std_fermi_fermi_eq_mockable() {
    if !guard_test("test_boundary_std_fermi_fermi_eq_mockable", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("std/fermi.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let lowered = lower(&dag).expect("lowering should succeed");
    let boundaries = detect_boundaries(&lowered.dag);
    assert!(boundaries.is_boundary_node(&"std.fermi::fermi_eq".into()), "std.fermi::fermi_eq should be a boundary");

    let mut mocks = mock_spec().to_boundary_mocks();
    mocks.set_value("std.fermi::fermi_eq", "return", Value::Bool(true));

    let log = execute_dag(&dag, ExecuteConfig { mode: ExecutionMode::DryRun(mocks), ..Default::default() }).unwrap();
    let entry = log.get("std.fermi::fermi_eq").expect("node should be in log");
    assert!(entry.was_intercepted, "boundary should be intercepted in dry-run");
}

