/// Node example: std.fermi::fermi_gte (example 0)
/// 
/// Tests that node 'std.fermi::fermi_gte' produces expected outputs for given inputs.
#[test]
fn test_example_std_fermi_fermi_gte_0() {
    if !guard_test("test_example_std_fermi_fermi_gte_0", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("std/fermi.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("__deps".to_string(), Value::List(vec![Value::Str("mock".to_string())]));
    inputs.insert("__out:return".to_string(), Value::Bool(true));
    inputs.insert("lhs".to_string(), Value::Enum { ty: "FermiDepth".to_string(), variant: "Xs".to_string() });
    inputs.insert("return".to_string(), Value::Bool(true));
    inputs.insert("rhs".to_string(), Value::Enum { ty: "FermiDepth".to_string(), variant: "Xs".to_string() });
    let outputs = gunbc_exec::execute_single_node(&dag, "std.fermi::fermi_gte", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'std.fermi::fermi_gte' should execute successfully");

    // Check output port 'return'
    let output_return = outputs.get("return").expect("output port 'return' should exist");
    assert!(output_return.as_bool().is_some() || matches!(*output_return, Value::Skipped), "expected Bool or Skipped for output_return");
}

